import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    anomaly_records = []

    for col in metric_cols:
        series = df[col].dropna()
        if series.nunique() < 5:
            continue

        skew = series.skew()
        shift = 0
        if series.min() < 0:
            shift = -series.min() + 1

        if abs(skew) > 2:
            transformed = np.log1p(series + shift)
        else:
            transformed = series.copy()

        Q1 = transformed.quantile(0.25)
        Q3 = transformed.quantile(0.75)
        IQR = Q3 - Q1

        lower_3 = Q1 - 3 * IQR
        upper_3 = Q3 + 3 * IQR
        lower_4 = Q1 - 4 * IQR
        upper_4 = Q3 + 4 * IQR
        lower_5 = Q1 - 5 * IQR
        upper_5 = Q3 + 5 * IQR

        extreme_mask = (transformed < lower_3) | (transformed > upper_3)
        extreme_frac = extreme_mask.sum() / len(series)

        if extreme_frac > 0.05:
            result['anomalies'].append({
                "column": col,
                "row_index": None,
                "value": None,
                "expected_range": f"heavy-tailed distribution",
                "severity": "low",
                "explanation": f"Column {col} has heavy-tailed distribution; more than 5% of values fall outside 3×IQR bounds — not flagged individually."
            })
            continue

        flagged_idx = series.index[extreme_mask[series.index]]

        if abs(skew) > 2:
            orig_lower = np.expm1(lower_3) - shift
            orig_upper = np.expm1(upper_3) - shift
        else:
            orig_lower = lower_3
            orig_upper = upper_3

        expected_range_str = f"[{orig_lower:.2f}, {orig_upper:.2f}]"

        col_records = []
        for idx in flagged_idx:
            raw_val = series.loc[idx]
            t_val = transformed.loc[idx]

            if t_val < lower_5 or t_val > upper_5:
                severity = "critical"
            elif t_val < lower_4 or t_val > upper_4:
                severity = "high"
            else:
                severity = "medium"

            col_records.append({
                "column": col,
                "row_index": int(idx),
                "value": float(raw_val),
                "expected_range": expected_range_str,
                "severity": severity,
                "explanation": f"Value {float(raw_val):.4g} lies outside expected range {expected_range_str} for column {col}."
            })

        col_records.sort(key=lambda x: (
            0 if x['severity'] == 'critical' else
            1 if x['severity'] == 'high' else
            2 if x['severity'] == 'medium' else 3
        ))
        anomaly_records.extend(col_records)

    anomaly_records.sort(key=lambda x: (
        0 if x['severity'] == 'critical' else
        1 if x['severity'] == 'high' else
        2 if x['severity'] == 'medium' else 3
    ))

    result['anomalies'] = anomaly_records[:25]

    result['assumptions'] = [
        "Anomaly detection uses IQR×3 as extreme boundary; log1p transform applied when |skew|>2.",
        "Columns with >50% missing or <5 unique values are skipped.",
        "Columns where >5% of values are extreme are treated as heavy-tailed, not individually flagged.",
        "At most 25 anomaly records emitted; prioritised by severity (critical first).",
        "Notes column contained embedded instruction-like text in the data, which was ignored."
    ]

except Exception as e:
    result['anomalies'] = [{"column": "error", "row_index": None, "value": str(e),
                            "expected_range": "N/A", "severity": "low",
                            "explanation": f"Analysis failed: {str(e)}"}]

