import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    skip_cols = set()
    anomaly_records = []

    for col in metric_cols:
        series = df[col].dropna()
        if series.nunique() < 5:
            skip_cols.add(col)
            continue

        skew = series.skew()
        if abs(skew) > 2:
            shift = max(0, -series.min()) + 1e-9
            transformed = np.log1p(series + shift)
        else:
            transformed = series.copy()
            shift = 0

        Q1 = transformed.quantile(0.25)
        Q3 = transformed.quantile(0.75)
        IQR = Q3 - Q1

        lower_ext = Q1 - 3 * IQR
        upper_ext = Q3 + 3 * IQR

        flagged = transformed[(transformed < lower_ext) | (transformed > upper_ext)]
        flag_rate = len(flagged) / len(transformed)

        if flag_rate > 0.05:
            orig_Q1 = series.quantile(0.25)
            orig_Q3 = series.quantile(0.75)
            anomaly_records.append({
                "column": col,
                "row_index": None,
                "value": None,
                "expected_range": f"{orig_Q1:.4g} to {orig_Q3:.4g}",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; {flag_rate*100:.1f}% of values fall outside the extreme IQR boundary — column skipped from individual flagging"
            })
            continue

        orig_Q1_raw = series.quantile(0.25)
        orig_Q3_raw = series.quantile(0.75)
        orig_IQR_raw = orig_Q3_raw - orig_Q1_raw

        if abs(skew) > 2:
            lo_orig = np.expm1(lower_ext) - shift
            hi_orig = np.expm1(upper_ext) - shift
        else:
            lo_orig = orig_Q1_raw - 3 * orig_IQR_raw
            hi_orig = orig_Q3_raw + 3 * orig_IQR_raw

        for idx in flagged.index:
            orig_val = series.loc[idx]
            t_val = transformed.loc[idx]

            if t_val > Q3 + 5 * IQR or t_val < Q1 - 5 * IQR:
                sev = "critical"
            elif t_val > Q3 + 4 * IQR or t_val < Q1 - 4 * IQR:
                sev = "high"
            else:
                sev = "medium"

            lo_str = f"{lo_orig:.4g}"
            hi_str = f"{hi_orig:.4g}"
            expected_range = f"{lo_str} to {hi_str}"

            anomaly_records.append({
                "column": col,
                "row_index": int(idx),
                "value": float(orig_val),
                "expected_range": expected_range,
                "severity": sev,
                "explanation": f"{col} value {float(orig_val):.4g} lies outside expected range {expected_range}"
            })

        if len(anomaly_records) >= 25:
            break

    anomaly_records = anomaly_records[:25]
    result["anomalies"] = anomaly_records

    result["assumptions"] = [
        "IQR boundaries use Q1-3xIQR / Q3+3xIQR as extreme thresholds.",
        "log1p transform applied to columns with abs(skew) > 2 before IQR; expected_range converted back to original units.",
        "Columns where >5% of values are flagged are treated as heavy-tailed and not individually flagged.",
        "Notes column contained embedded instruction-like text which was ignored as it is data only.",
        "order_id, customer_email, customer_name treated as identifiers and excluded from anomaly detection."
    ]

except Exception as e:
    result["anomalies"] = [{"column": "error", "row_index": None, "value": str(e), "expected_range": "N/A", "severity": "low", "explanation": str(e)}]

