# ─── Standard statistics (deterministic) ───
result['builtin'] = []
_targets, _segs, _date, _hints = ['salary'], [], 'hire_date', {'salary': ['mean', [], None]}
try:
    if False:
        for _i, _a in enumerate(_targets):
