    monthly_temp = df.groupby('month')['temperature'].mean().sort_index()

    trend_results = []

    if len(monthly_temp) >= 2:
        periods = monthly_temp.index.tolist()
        last_period = periods[-1]
        prev_period = periods[-2]
        last_val = float(monthly_temp.iloc[-1])
        prev_val = float(monthly_temp.iloc[-2])
        pct_change = float((last_val - prev_val) / prev_val * 100) if prev_val != 0 else 0.0
        direction = "up" if pct_change > 0.5 else ("down" if pct_change < -0.5 else "flat")
        trend_results.append({
            "column": "temperature",
            "period": "MoM",
            "direction": direction,
            "pct_change": round(pct_change, 4),
            "segment": None
        })

    if 'line' in df.columns:
        for line_val, grp in df.groupby('line'):
            grp_monthly = grp.groupby('month')['temperature'].mean().sort_index()
            if len(grp_monthly) >= 2:
                lv = float(grp_monthly.iloc[-1])
                pv = float(grp_monthly.iloc[-2])
                pc = float((lv - pv) / pv * 100) if pv != 0 else 0.0
                d = "up" if pc > 0.5 else ("down" if pc < -0.5 else "flat")
                trend_results.append({
                    "column": "temperature",
                    "period": "MoM",
                    "direction": d,
                    "pct_change": round(pc, 4),
                    "segment": str(line_val)
                })

    df['week'] = df['reading_time'].dt.to_period('W')
    weekly_temp = df.groupby('week')['temperature'].mean().sort_index()
    if len(weekly_temp) >= 7:
        rolling_vals = weekly_temp.values
        recent_avg = float(rolling_vals[-1])
        prior_avg = float(rolling_vals[-7])
        pc_7d = float((recent_avg - prior_avg) / prior_avg * 100) if prior_avg != 0 else 0.0
        d_7d = "up" if pc_7d > 0.5 else ("down" if pc_7d < -0.5 else "flat")
        trend_results.append({
            "column": "temperature",
            "period": "7d_rolling",
            "direction": d_7d,
            "pct_change": round(pc_7d, 4),
            "segment": None
        })

    result['trends'] = trend_results
    result['assumptions'] = [
        "MoM compares calendar-month means of temperature.",
        "7d_rolling compares weekly means (last week vs 7 weeks prior).",
        "Segment trends computed per line value independently.",
        "reading_time parsed as datetime; rows with null timestamps excluded.",
        "Direction threshold: >0.5% change is up/down, else flat."
    ]

except Exception as e:
    result['trends'] = [{"column": "temperature", "period": "MoM", "direction": "flat", "pct_change": 0.0, "segment": None}]
    result['assumptions'] = [f"Trend analysis failed: {str(e)}"]

