    df_sorted = df.sort_values(['account_id', 'month'])
    monthly_last = df_sorted.groupby(['account_id', 'month']).last().reset_index()

    # Monthly MRR: sum of last values per account per month
    monthly_mrr = monthly_last.groupby('month')['mrr'].sum().reset_index()
    monthly_mrr = monthly_mrr.sort_values('month')

    if len(monthly_mrr) >= 2:
        last_month_val = monthly_mrr.iloc[-1]['mrr']
        prev_month_val = monthly_mrr.iloc[-2]['mrr']
        last_month_label = monthly_mrr.iloc[-1]['month'].strftime('%Y-%m')
        prev_month_label = monthly_mrr.iloc[-2]['month'].strftime('%Y-%m')

        pct_change = ((last_month_val - prev_month_val) / prev_month_val) * 100 if prev_month_val != 0 else 0.0
        direction = "up" if pct_change > 0.5 else ("down" if pct_change < -0.5 else "flat")

        result['trends'].append({
            "column": "mrr",
            "period": "MoM",
            "direction": direction,
            "pct_change": round(pct_change, 4),
            "segment": None
        })

        # Per-plan MoM trend
        monthly_plan_mrr = monthly_last.groupby(['month', 'plan'])['mrr'].sum().reset_index()
        monthly_plan_mrr = monthly_plan_mrr.sort_values(['plan', 'month'])

        for plan_val, grp in monthly_plan_mrr.groupby('plan'):
            grp = grp.sort_values('month')
            if len(grp) >= 2:
                p_last = grp.iloc[-1]['mrr']
                p_prev = grp.iloc[-2]['mrr']
                p_pct = ((p_last - p_prev) / p_prev) * 100 if p_prev != 0 else 0.0
                p_dir = "up" if p_pct > 0.5 else ("down" if p_pct < -0.5 else "flat")
                result['trends'].append({
                    "column": "mrr",
                    "period": "MoM",
                    "direction": p_dir,
                    "pct_change": round(p_pct, 4),
                    "segment": str(plan_val)
                })

    result['assumptions'].append(
        "MRR is treated as a level metric: per month, each account's last value is taken, then summed across accounts."
    )
    result['assumptions'].append(
        f"MoM compares the two most recent calendar months in the dataset."
    )

