try:
    region_revenue = df.groupby('region')['revenue'].agg(['sum', 'mean', 'count']).reset_index()
    region_revenue = region_revenue.sort_values('count', ascending=False).head(10)

    result['segments'].append({
        "segment_column": "region",
        "metric_column": "revenue",
        "aggregation": "sum",
        "label": "total_revenue_by_region",
        "results": [
            {"name": str(row['region']), "value": round(float(row['sum']), 4)}
            for _, row in region_revenue.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "region",
        "metric_column": "revenue",
        "aggregation": "mean",
        "label": "avg_revenue_by_region",
        "results": [
            {"name": str(row['region']), "value": round(float(row['mean']), 4)}
            for _, row in region_revenue.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "region",
        "metric_column": "revenue",
        "aggregation": "count",
        "label": "order_count_by_region",
        "results": [
            {"name": str(row['region']), "value": float(row['count'])}
            for _, row in region_revenue.iterrows()
        ]
    })
except Exception as e:
    result['assumptions'].append(f"Region-revenue segmentation failed: {str(e)}")

try:
    from scipy import stats as sp_stats
    regions = df['region'].dropna().unique()
    groups = [df.loc[df['region'] == r, 'revenue'].dropna().values for r in regions]
    groups = [g for g in groups if len(g) >= 2]
    if len(groups) >= 2:
        stat, p = sp_stats.f_oneway(*groups)
        stat = round(float(stat), 4)
        p = round(float(p), 6)
        interp = f"One-way ANOVA across regions: F={stat}, p={p}. " + (
            "Significant difference in mean revenue across regions." if p < 0.05
            else "No significant difference in mean revenue across regions."
        )
        result['statistical_tests'].append({
            "test_name": "One-way ANOVA (revenue by region)",
            "statistic": stat,
            "p_value": p,
            "interpretation": interp
        })
except Exception as e:
    result['assumptions'].append(f"ANOVA test failed: {str(e)}")

