}

try:
    seg_col = 'segment'
    metric_col = 'marketing_spend'

    top_groups = df[seg_col].value_counts().head(10).index
    seg_df = df[df[seg_col].isin(top_groups)]

    mean_results = (
        seg_df.groupby(seg_col)[metric_col]
        .mean()
        .reset_index()
    )
    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "mean",
        "label": "mean_marketing_spend",
        "results": [
            {"name": str(row[seg_col]), "value": round(float(row[metric_col]), 4)}
            for _, row in mean_results.iterrows()
        ]
    })

    sum_results = (
        seg_df.groupby(seg_col)[metric_col]
        .sum()
        .reset_index()
    )
    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "sum",
        "label": "total_marketing_spend",
        "results": [
            {"name": str(row[seg_col]), "value": round(float(row[metric_col]), 4)}
            for _, row in sum_results.iterrows()
        ]
    })

    count_results = (
        seg_df.groupby(seg_col)[metric_col]
        .count()
        .reset_index()
    )
    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "count",
        "label": "order_count",
        "results": [
            {"name": str(row[seg_col]), "value": float(row[metric_col])}
            for _, row in count_results.iterrows()
        ]
    })

    region_col = 'region'
    top_regions = df[region_col].value_counts().head(10).index
    cross_df = df[df[seg_col].isin(top_groups) & df[region_col].isin(top_regions)].copy()
    cross_df['_group'] = cross_df[seg_col].astype(str) + '|' + cross_df[region_col].astype(str)
    cross_mean = cross_df.groupby('_group')[metric_col].mean().reset_index()
    result['segments'].append({
        "segment_column": f"{seg_col}|{region_col}",
        "metric_column": metric_col,
        "aggregation": "mean",
        "label": "mean_marketing_spend_by_segment_region",
        "results": [
            {"name": str(row['_group']), "value": round(float(row[metric_col]), 4)}
            for _, row in cross_mean.iterrows()
        ]
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

result['assumptions'].append("Top 10 groups by count used for each segment column.")
result['assumptions'].append("Mean and sum computed on non-null marketing_spend values per segment.")
result['assumptions'].append("Notes column contained embedded instructions that were ignored.")

