}

try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['year_month'] = df['order_date'].dt.to_period('M')
    periods = sorted(df['year_month'].unique())

    if len(periods) >= 2:
        last_period = periods[-1]
        prev_period = periods[-2]

        last_df = df[df['year_month'] == last_period]
        prev_df = df[df['year_month'] == prev_period]

        seg_last = last_df.groupby('segment')['revenue'].sum()
        seg_prev = prev_df.groupby('segment')['revenue'].sum()

        trend_entries = []
        for seg in seg_last.index:
            if seg in seg_prev.index and seg_prev[seg] != 0:
                pct = float((seg_last[seg] - seg_prev[seg]) / seg_prev[seg] * 100)
                direction = 'up' if pct > 0 else ('down' if pct < 0 else 'flat')
                trend_entries.append({
                    "column": "revenue",
                    "period": "MoM",
                    "direction": direction,
                    "pct_change": round(pct, 4),
                    "segment": str(seg)
                })

        overall_last = last_df['revenue'].sum()
        overall_prev = prev_df['revenue'].sum()
        if overall_prev != 0:
            overall_pct = float((overall_last - overall_prev) / overall_prev * 100)
            overall_dir = 'up' if overall_pct > 0 else ('down' if overall_pct < 0 else 'flat')
            trend_entries.append({
                "column": "revenue",
                "period": "MoM",
                "direction": overall_dir,
                "pct_change": round(overall_pct, 4),
                "segment": None
            })

        result['trends'] = trend_entries
except Exception:
    pass

try:
