    df['year_month'] = df['order_date'].dt.to_period('M')

    segments = df['segment'].dropna().unique()

    for seg in segments:
        seg_df = df[df['segment'] == seg].copy()
        monthly = seg_df.groupby('year_month')['revenue'].sum().sort_index()
        if len(monthly) < 2:
            continue
        periods = monthly.index.tolist()
        first_val = float(monthly.iloc[0])
        last_val = float(monthly.iloc[-1])
        if first_val == 0:
            pct = 0.0
        else:
            pct = round((last_val - first_val) / abs(first_val) * 100, 2)
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            "column": "revenue",
            "period": "MoM",
            "direction": direction,
            "pct_change": pct,
            "segment": str(seg)
        })

    overall_monthly = df.groupby('year_month')['revenue'].sum().sort_index()
    if len(overall_monthly) >= 2:
        first_val = float(overall_monthly.iloc[0])
        last_val = float(overall_monthly.iloc[-1])
        pct = round((last_val - first_val) / abs(first_val) * 100, 2) if first_val != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            "column": "revenue",
            "period": "MoM",
            "direction": direction,
            "pct_change": pct,
            "segment": None
        })
except Exception:
    pass

