import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np
    from scipy import stats

    # Conversion rate by group (control vs treatment)
    group_conv = df.groupby('group')['converted'].agg(['mean', 'sum', 'count']).reset_index()
    group_results = [{"name": str(row['group']), "value": float(row['mean'])} for _, row in group_conv.iterrows()]
    result['segments'].append({
        "segment_column": "group",
        "metric_column": "converted",
        "aggregation": "ratio",
        "label": "conversion_rate",
        "results": group_results
    })

    # Conversion rate by department
    dept_conv = df.groupby('department')['converted'].agg(['mean', 'count']).reset_index()
    dept_conv_sorted = dept_conv.nlargest(10, 'count')
    dept_results = [{"name": str(row['department']), "value": float(row['mean'])} for _, row in dept_conv_sorted.iterrows()]
    result['segments'].append({
        "segment_column": "department",
        "metric_column": "converted",
        "aggregation": "ratio",
        "label": "conversion_rate",
        "results": dept_results
    })

    # Conversion rate by group x department (joint breakdown)
    joint = df.groupby(['group', 'department'])['converted'].mean().reset_index()
    joint_results = [{"name": f"{row['group']}|{row['department']}", "value": float(row['converted'])} for _, row in joint.iterrows()]
    result['segments'].append({
        "segment_column": "group|department",
        "metric_column": "converted",
        "aggregation": "ratio",
        "label": "conversion_rate",
        "results": joint_results
    })

    # Session minutes by group
    grp_sess = df.groupby('group')['session_minutes'].mean().reset_index()
    sess_results = [{"name": str(row['group']), "value": float(row['session_minutes'])} for _, row in grp_sess.iterrows()]
    result['segments'].append({
        "segment_column": "group",
        "metric_column": "session_minutes",
        "aggregation": "mean",
        "label": None,
        "results": sess_results
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation partial failure: {str(e)}")

try:
    # Chi-square test: group vs converted
    ct = df.groupby(['group', 'converted']).size().unstack(fill_value=0)
    chi2, p_chi2, dof, _ = stats.chi2_contingency(ct)
    chi2 = float(chi2)
    p_chi2 = float(p_chi2)
    interp_chi2 = (
        f"Chi-square test of independence between group and converted: "
        f"chi2={chi2:.3f}, p={p_chi2:.3g}, dof={dof}. "
        + ("Significant association — treatment affects conversion." if p_chi2 < 0.05
           else "No significant relationship between group and conversion.")
    )
    result['statistical_tests'].append({
        "test_name": "chi_square_group_vs_converted",
        "statistic": chi2,
        "p_value": p_chi2,
        "interpretation": interp_chi2
    })

    # Two-sample t-test on session_minutes: control vs treatment
    ctrl_sess = df[df['group'] == 'control']['session_minutes'].dropna()
    trt_sess = df[df['group'] == 'treatment']['session_minutes'].dropna()
    t_stat, p_t = stats.ttest_ind(ctrl_sess, trt_sess, equal_var=False)
    t_stat = float(t_stat)
    p_t = float(p_t)
    interp_t = (
        f"Welch t-test on session_minutes (control vs treatment): "
        f"t={t_stat:.3f}, p={p_t:.3g}. "
        + ("Significant difference in session duration between groups." if p_t < 0.05
           else "No significant relationship between group and session_minutes.")
    )
    result['statistical_tests'].append({
        "test_name": "ttest_session_minutes_group",
        "statistic": t_stat,
        "p_value": p_t,
        "interpretation": interp_t
    })

    # Per-department chi-square (Simpson's paradox check)
    departments = df['department'].dropna().unique()
    for dept in departments:
        sub = df[df['department'] == dept]
        if sub['group'].nunique() < 2:
            continue
        ct_d = sub.groupby(['group', 'converted']).size().unstack(fill_value=0)
        if ct_d.shape != (2, 2):
            continue
        chi2_d, p_d, dof_d, _ = stats.chi2_contingency(ct_d)
        chi2_d = float(chi2_d)
        p_d = float(p_d)
        interp_d = (
            f"Chi-square (group vs converted) within department={dept}: "
            f"chi2={chi2_d:.3f}, p={p_d:.3g}. "
            + ("Significant association within stratum." if p_d < 0.05
               else "No significant relationship within this stratum.")
        )
        result['statistical_tests'].append({
            "test_name": f"chi_square_group_vs_converted_dept_{dept}",
            "statistic": chi2_d,
            "p_value": p_d,
            "interpretation": interp_d
        })

except Exception as e:
    result['assumptions'].append(f"Hypothesis testing partial failure: {str(e)}")

result['assumptions'].append("Conversion rate computed as mean of binary converted column (0/1).")
result['assumptions'].append("Chi-square used for group vs converted; Welch t-test for session_minutes.")
result['assumptions'].append("Per-department tests check for Simpson's paradox in group effect.")

# ─── Standard statistics (deterministic) ───
result['builtin'] = []
_targets, _segs, _date, _hints = ['converted'], ['group', 'department'], None, {}
try:
    if True:
        for _i, _a in enumerate(_targets):
            for _b in _targets[_i + 1:]:
                if f'{_a}__{_b}' not in result['correlations'] and f'{_b}__{_a}' not in result['correlations']:
                    _r = df[_a].corr(df[_b])
                    if _r == _r:
                        result['correlations'][f'{_a}__{_b}'] = round(float(_r), 4)
                        result['builtin'].append(f'corr:{_a}__{_b}')
except Exception:
    pass
try:
    if (_date or _hints) and False:
        # A mid-month export compares the last two complete months (agents.utils.partial_last_month).
        def _cut(_t):
            _mm = _t.dt.to_period('M')
            _d = _t.dropna()
            if _d.empty:
                return _mm
            _days = _d.dt.normalize().groupby(_d.dt.to_period('M')).nunique().sort_index()
            if len(_days) >= 3 and _d.max().normalize() < _d.max().normalize() + pd.offsets.MonthEnd(0) and _days.iloc[-1] < 0.9 * _days.iloc[:-1].median():
                _mm = _mm.where(_mm != _days.index[-1])
